s=np.array([90,100,110,120]);pay=np.maximum(s-100,0);price=pay/1.05;ax.step(s,pay,where='mid',color=BAD,lw=2,label='Terminal payoff');ax.plot(s,price,'o-',color=ACCENT,label='Discounted state value');ax.set_xlabel('Underlying price at expiry (USD/share)');ax.set_ylabel('USD/share');ax.set_title("Payoff is not today's option price",loc='left');ax.legend(fontsize=7);ax.grid(alpha=.25)
